const { setWorldConstructor, World } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  async loadApp() {
    const htmlPath = path.join(__dirname, '..', '..', 'assets', 'app-template.index.html');
    let html = fs.readFileSync(htmlPath, 'utf-8');

    // Fix paths to be absolute for happy-dom
    html = html.replace(/href="node_modules\//g, 'href="');
    html = html.replace(/src="node_modules\//g, 'src="');
    html = html.replace(/src="js\/app\.js"/g, '<script>/* app.js placeholder */</script>');

    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    this.document.open();
    this.document.write(html);
    this.document.close();

    // Clear localStorage
    this.window.localStorage.clear();
  }

  async loadAppWithJs() {
    const htmlPath = path.join(__dirname, '..', '..', 'assets', 'app-template.index.html');
    let html = fs.readFileSync(htmlPath, 'utf-8');

    // Fix paths to be absolute for happy-dom
    html = html.replace(/href="node_modules\//g, 'href="');
    html = html.replace(/src="node_modules\//g, 'src="');

    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    this.document.open();
    this.document.write(html);
    this.document.close();

    // Load the app.js
    const appPath = path.join(__dirname, '..', '..', 'js', 'app.js');
    if (fs.existsSync(appPath)) {
      const appCode = fs.readFileSync(appPath, 'utf-8');
      // Execute the app code in the window context
      const script = this.document.createElement('script');
      script.textContent = appCode;
      this.document.body.appendChild(script);
    }
  }

  async addTodo(title) {
    const input = this.document.querySelector('.new-todo');
    input.value = title;
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
    // Trigger input event for frameworks
    input.dispatchEvent(new this.window.Event('input'));
    // Also try submit event on the form
    const form = input.closest('form') || input.parentElement;
    if (form) {
      form.dispatchEvent(new this.window.Event('submit'));
    }
  }

  async addTodos(titles) {
    for (const title of titles) {
      await this.addTodo(title);
    }
  }

  async toggleTodo(title, completed) {
    const labels = this.document.querySelectorAll('.todo-list label');
    for (const label of labels) {
      if (label.textContent === title) {
        const toggle = label.closest('.view').querySelector('.toggle');
        if (toggle.checked !== completed) {
          toggle.click();
        }
        break;
      }
    }
  }

  async completeTodo(title) {
    await this.toggleTodo(title, true);
  }

  async clickToggleAll() {
    const toggleAll = this.document.querySelector('#toggle-all');
    toggleAll.click();
  }

  getTodoElements() {
    return this.document.querySelectorAll('.todo-list li');
  }

  getVisibleTodos() {
    const todos = this.getTodoElements();
    return Array.from(todos).filter(li => {
      const style = this.window.getComputedStyle(li);
      return style.display !== 'none';
    });
  }

  getCompletedCount() {
    return this.document.querySelectorAll('.todo-list li.completed').length;
  }

  getCounterText() {
    const strong = this.document.querySelector('.todo-count strong');
    return strong ? strong.textContent : '';
  }

  navigateTo(route) {
    this.window.location.hash = route;
    // Trigger hashchange
    this.window.dispatchEvent(new this.window.HashChangeEvent('hashchange'));
  }

  async reloadPage() {
    // Save current state
    const todos = [];
    this.getTodoElements().forEach(li => {
      const label = li.querySelector('label');
      const completed = li.classList.contains('completed');
      todos.push({ title: label.textContent, completed });
    });

    // Save to localStorage
    const storageKey = 'todos-javascript-app';
    this.window.localStorage.setItem(storageKey, JSON.stringify(todos));

    // Reload by reinitializing
    await this.loadAppWithJs();

    // Re-dispatch hashchange
    this.window.dispatchEvent(new this.window.HashChangeEvent('hashchange'));
  }
}

