const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// --- Setup steps (Given) ---

Given('the app is loaded with no existing todos', async function () {
  await this.loadAppWithJs();
});

Given('the new todo input is focused', async function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(this.document.activeElement, input);
});

Given('the new todo input is empty', async function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '');
});

Given('the user has added a todo {string}', async function (title) {
  await this.addTodo(title);
});

Given('the user has added todos {string} and {string}', async function (title1, title2) {
  await this.addTodos([title1, title2]);
});

Given('the todo {string} is completed', async function (title) {
  await this.completeTodo(title);
});

Given('the todo {string} is not completed', async function (title) {
  await this.toggleTodo(title, false);
});

Given('all todos are completed', async function () {
  const todos = this.getTodoElements();
  for (const li of todos) {
    const toggle = li.querySelector('.toggle');
    if (!toggle.checked) {
      toggle.click();
    }
  }
});

Given('the todo {string} appears in the list', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  assert.ok(found, `Todo "${title}" not found in list`);
});

Given('the todo {string} is in edit mode', async function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      label.dispatchEvent(new this.window.DoubleClickEvent('dblclick'));
      break;
    }
  }
  const li = label.closest('li');
  assert.ok(li.classList.contains('editing'), `Todo "${title}" is not in edit mode`);
});

Given('the todo {string} is not in edit mode', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      assert.ok(!li.classList.contains('editing'), `Todo "${title}" is in edit mode`);
      break;
    }
  }
});

Given('the edit input contains {string}', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'No editing todo found');
  assert.strictEqual(editInput.value, text);
});

Given('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.ok(toggleAll.checked, 'Toggle-all is not checked');
});

Given('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  assert.notStrictEqual(style.display, 'none');
});

Given('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  assert.strictEqual(style.display, 'none');
});

Given('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  assert.notStrictEqual(style.display, 'none');
});

Given('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  assert.strictEqual(style.display, 'none');
});

Given('the todo {string} is visible', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const style = this.window.getComputedStyle(li);
      assert.notStrictEqual(style.display, 'none', `Todo "${title}" is hidden`);
      break;
    }
  }
});

Given('the todo {string} is hidden', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const style = this.window.getComputedStyle(li);
      assert.strictEqual(style.display, 'none', `Todo "${title}" is visible`);
      break;
    }
  }
});

Given('the todo {string} remains', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  assert.ok(found, `Todo "${title}" should remain in the list`);
});

// --- Action steps (When) ---

When('the user types {string} and presses Enter', async function (text) {
  await this.addTodo(text);
});

