  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'No editing todo found');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
});

When('the user types {string} in the edit input and presses Escape', async function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'No editing todo found');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27 }));
});

When('the user types {string} in the edit input and blurs', async function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'No editing todo found');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('blur'));
});

When('the user clears the edit input and presses Enter', async function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'No editing todo found');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
});

