  await this.clickToggleAll();
});

When('the user completes all todos individually', async function () {
  const todos = this.getTodoElements();
  for (const li of todos) {
    const toggle = li.querySelector('.toggle');
    if (!toggle.checked) {
      toggle.click();
    }
  }
});

When('the user completes the todo {string}', async function (title) {
  await this.completeTodo(title);
});

When('the user clicks {string}', async function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    btn.click();
  }
});

When('the user clicks the destroy button for {string}', async function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const destroy = label.closest('.view').querySelector('.destroy');
      destroy.click();
      break;
    }
  }
});

When('the user navigates to {string}', async function (route) {
  this.navigateTo(route);
});

When('the page is reloaded', async function () {
  await this.reloadPage();
});

// --- Assertion steps (Then) ---

Then('a todo {string} appears in the list', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  assert.ok(found, `Todo "${title}" not found in list`);
});

Then('the todo list is empty', function () {
  const todos = this.getTodoElements();
  assert.strictEqual(todos.length, 0, `Expected 0 todos, found ${todos.length}`);
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '');
});

Then('the new todo input has focus', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(this.document.activeElement, input);
});

Then('all todos are completed', function () {
  const todos = this.getTodoElements();
  assert.ok(todos.length > 0, 'No todos found');
  for (const li of todos) {
    assert.ok(li.classList.contains('completed'), 'Not all todos are completed');
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.ok(toggleAll.checked, 'Toggle-all is not checked');
});

Then('the toggle-all checkbox is unchecked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.ok(!toggleAll.checked, 'Toggle-all is checked');
});

Then('the counter shows {string}', function (text) {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'Counter not found');
  assert.strictEqual(strong.textContent, text);
});

Then('the {string} button is hidden', function (buttonText) {
  if (buttonText === 'Clear completed') {
