(function() {
  'use strict';

  // Storage key
  var STORAGE_KEY = 'todos-javascript-app';

  // State
  var todos = [];
  var editingId = null;

  // DOM references
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('#toggle-all');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelectorAll('.filters a');

  // Initialize
  function init() {
    loadFromStorage();
    render();
    setupEventListeners();
    newTodoInput.focus();
  }

  // Load from localStorage
  function loadFromStorage() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        todos = JSON.parse(stored);
      }
    } catch (e) {
      todos = [];
    }
  }

  // Save to localStorage
  function saveToStorage() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) {
      // Ignore storage errors
    }
  }

  // Generate unique ID
  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  // Add todo
  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({
      id: generateId(),
      title: title,
      completed: false
    });
    saveToStorage();
    render();
    newTodoInput.value = '';
    newTodoInput.focus();
  }

  // Toggle todo completion
  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveToStorage();
    render();
  }

  // Remove todo
  function removeTodo(id) {
    todos = todos.filter(function(todo) {
      return todo.id !== id;
    });
    saveToStorage();
    render();
  }

  // Edit todo
  function editTodo(id, newTitle) {
    newTitle = newTitle.trim();
    if (!newTitle) {
      removeTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = newTitle;
        break;
      }
    }
    editingId = null;
    saveToStorage();
    render();
  }

  // Toggle all
  function toggleAll() {
    var allCompleted = todos.every(function(todo) {
      return todo.completed;
    });
    todos.forEach(function(todo) {
      todo.completed = !allCompleted;
    });
    saveToStorage();
    render();
  }

  // Clear completed
  function clearCompletedTodos() {
    todos = todos.filter(function(todo) {
      return !todo.completed;
    });
    saveToStorage();
    render();
  }

  // Get current filter
  function getCurrentFilter() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  // Get filtered todos
  function getFilteredTodos() {
    var filter = getCurrentFilter();
    return todos.filter(function(todo) {
      if (filter === 'active') return !todo.completed;
      if (filter === 'completed') return todo.completed;
      return true;
    });
  }

  // Render
  function render() {
    var filteredTodos = getFilteredTodos();
    var activeCount = todos.filter(function(todo) {
      return !todo.completed;
    }).length;
    var completedCount = todos.filter(function(todo) {
      return todo.completed;
    }).length;

    // Render todo list
    todoList.innerHTML = '';
    filteredTodos.forEach(function(todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');
      if (editingId === todo.id) li.classList.add('editing');

      li.innerHTML = '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
        '<label>' + escapeHtml(todo.title) + '</label>' +
        '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      todoList.appendChild(li);
    });

    // Update counter
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

    // Show/hide main and footer
    mainSection.style.display = todos.length > 0 ? '' : 'none';
    footer.style.display = todos.length > 0 ? '' : 'none';

    // Update toggle-all
    toggleAll.checked = todos.length > 0 && todos.every(function(todo) {
      return todo.completed;
    });

    // Update clear completed button
    clearCompleted.style.display = completedCount > 0 ? '' : 'none';

    // Update filter links
    var currentFilter = getCurrentFilter();
    filters.forEach(function(a) {
      var filterName = a.textContent.toLowerCase();
      if (filterName === currentFilter) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    });

    // Focus edit input if editing
    if (editingId) {
      var editInput = todoList.querySelector('li.editing .edit');
      if (editInput) {
        editInput.focus();
      }
    }
  }

  // Escape HTML
  function escapeHtml(text) {
    var div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // Setup event listeners
  function setupEventListeners() {
    // New todo input
    newTodoInput.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.keyCode === 13) {
        addTodo(newTodoInput.value);
      }
    });

    // Toggle all
    toggleAll.addEventListener('change', function() {
      toggleAll();
    });

    // Clear completed
    clearCompleted.addEventListener('click', function() {
      clearCompletedTodos();
    });

    // Todo list events (delegation)
    todoList.addEventListener('click', function(e) {
      var target = e.target;
      var li = target.closest('li');
      if (!li) return;
      var id = li.dataset.id;

      if (target.classList.contains('toggle')) {
        toggleTodo(id);
      } else if (target.classList.contains('destroy')) {
        removeTodo(id);
      }
    });

    // Double-click to edit
    todoList.addEventListener('dblclick', function(e) {
      var target = e.target;
      if (target.tagName === 'LABEL') {
        var li = target.closest('li');
        if (li) {
          editingId = li.dataset.id;
          render();
        }
      }
    });

    // Edit input events
    todoList.addEventListener('keydown', function(e) {
      var target = e.target;
      if (target.classList.contains('edit')) {
        var li = target.closest('li');
        if (!li) return;
        var id = li.dataset.id;

        if (e.key === 'Enter' || e.keyCode === 13) {
          editTodo(id, target.value);
        } else if (e.key === 'Escape' || e.keyCode === 27) {
          editingId = null;
          render();
        }
      }
    });

    todoList.addEventListener('blur', function(e) {
      var target = e.target;
      if (target.classList.contains('edit')) {
        var li = target.closest('li');
        if (!li) return;
        var id = li.dataset.id;
        editTodo(id, target.value);
      }
    }, true);

    // Hash change for routing
    window.addEventListener('hashchange', function() {
      render();
    });
  }

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

