When('the user completes all todos individually', async function () {
  // Keep re-querying until all are completed
  let allCompleted = false;
  while (!allCompleted) {
    const todos = this.getTodoElements();
    let found = false;
    for (const li of todos) {
      const toggle = li.querySelector('.toggle');
      if (!toggle.checked) {
        toggle.click();
        found = true;
        break; // Re-query after render
      }
    }
    allCompleted = !found;
  }
});

